            "R4C2"
          ]
        }
      ]
    }
  ],
  "options": {
    "preserve_non_table_cells": true
  }
}

Example filename: sparse-headers.json
{
  "version": "0.1",
  "sheet": "Revenue",
  "tables": [
    {
      "name": "quarterly_revenue",
      "values": {
        "name": "revenue",
        "cells": {
